// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT, LogFile} from "../src/ACCURAL_DEPOSIT.sol";

contract Reverter {
    receive() external payable { revert(); }
    fallback() external payable { revert(); }
}

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    Reverter reverter;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
        reverter = new Reverter();
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        // Keep the fuzzed deposit/collect domain wide but admissible.
        depositAmount = bound(depositAmount, 1 ether, 10 ether);
        collectAmount = bound(collectAmount, 1 ether, depositAmount);

        address actor = address(0xBEEF);
        vm.deal(actor, depositAmount);

        // Set up the LogFile first, because C's Deposit and Collect call it and
        // a plain address has no code, causing those calls to revert.
        LogFile logFile = new LogFile();
        c.SetLogFile(address(logFile));
        c.Initialized();

        // Deposit enough balance for the actor so Collect's guard passes.
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Make the actor's address fail on ether receipt by deploying a
        // reverter at that address? No: the actor must remain an EOA for
        // Deposit, and the external call in Collect goes to msg.sender.
        // Instead, use a contract as the actor so that the call in Collect
        // fails. The contract must be able to call Deposit with value, so
        // it needs a payable function and a receive fallback.
        FailingActor failingActor = new FailingActor(address(c));
        vm.deal(address(failingActor), depositAmount);

        // The failing actor deposits; its own balance tracks deposits in C,
        // even though it reverts on receipt of ether during Collect.
        failingActor.deposit{value: depositAmount}();

        // Now ask C to collect from the failing actor. The external call to
        // msg.sender will fail because FailingActor reverts in receive();
        // the correct Collect reverts and leaves balances unchanged, the
        // buggy Collect succeeds and subtracts the amount.
        uint256 beforeBalance = c.balances(address(failingActor));
        bool callOk = true;
        try failingActor.collect(collectAmount) {
            callOk = true;
        } catch {
            callOk = false;
        }

        uint256 afterBalance = c.balances(address(failingActor));

        // General rule: if the failed external transfer is correctly
        // propagated, the Collect call must revert, so callOk is false and
        // the balance is unchanged. The buggy version has callOk true and
        // balance reduced.
        assertTrue(!callOk && afterBalance == beforeBalance);
    }
}

contract FailingActor {
    ACCURAL_DEPOSIT internal c;

    constructor(address _c) {
        c = ACCURAL_DEPOSIT(payable(_c));
    }

    function deposit() external payable {
        c.Deposit{value: msg.value}();
    }

    function collect(uint256 amount) external {
        c.Collect(amount);
    }

    receive() external payable {
        revert();
    }
}
